 function getPDF(){
   var cache_width = $('#renderPDF').width(); //Criado um cache do CSS
   var a4  =[ 595.28,  841.89]; // Widht e Height de uma folha a4
   // Setar o width da div no formato a4
   $("#renderPDF").width((a4[0]*1.33333) -80).css('max-width','none');
    // Aqui ele cria a imagem e cria o pdf
     html2canvas($('#renderPDF'), {
     onrendered: function(canvas) {
     //*********Lu adicionei a linha 10 e 13********* 
     var imgData = 'data:image/png;base64,'; 
     var img = canvas.toDataURL("image/png",1.0);
     var doc = new jsPDF({unit:'px', format:'a4'});     
     doc.addImage(imgData, 'JPEG', 15,10,10,10);
     doc.addImage(img, 'JPEG', 10, 30);
     doc.save('Solemar_curriculum');
     //Retorna ao CSS normal
     $('#renderPDF').width(cache_width);
      }
    });
}
   
